// Emit one item per Meta-active client, carrying two windows.
//
// ── Why two windows, and why neither is "yesterday" ───────────────────────
// The hourly ad workflow once fetched yesterday only, with no catch-up. A
// single failed run left a permanent hole, and by the time anyone looked, 58%
// of Meta spend was missing from the warehouse with nothing alerting on it. A
// rolling re-fetch self-heals: every run rewrites the window, and stg dedupes
// on (client, entity, date) keeping the newest row, so overlap is free.
//
// Ad-set grain gets 35 days. Meta restates conversions for roughly a month, so
// anything shorter locks in figures that were still moving.
//
// Breakdowns get 7. The row multiplier is ~12x for age x gender and ~8x for
// placement, and they exist for delivery diagnosis on current delivery, not as
// a history to trend. Older rows already in the table are kept, not deleted —
// the window governs what is re-fetched, not what is retained.
const ADSET_DAYS = 35;
const BREAKDOWN_DAYS = 7;

const ymd = d => d.toISOString().slice(0, 10);
const back = n => { const d = new Date(); d.setUTCDate(d.getUTCDate() - n); return ymd(d); };
const until = back(1);   // yesterday: today is always partial

return $input.all().map(item => ({ json: {
  client_id: item.json.client_id,
  slug: item.json.slug,
  currency: item.json.currency,
  adset_range:     `{"since":"${back(ADSET_DAYS)}","until":"${until}"}`,
  breakdown_range: `{"since":"${back(BREAKDOWN_DAYS)}","until":"${until}"}`
}}));

// Secrets, decoded once per client. `.first()` deliberately, never `.item`:
// resolving a paired item across a chain this wide makes n8n walk the whole
// execution graph per row and peg a CPU core with zero network activity.
const decode = b64 => Buffer.from(b64, 'base64').toString('utf8').trim();
const item = $('Loop over clients').first().json;

return [{ json: {
  client_id: item.client_id,
  slug: item.slug,
  currency: item.currency,
  adset_range: item.adset_range,
  breakdown_range: item.breakdown_range,
  access_token: decode($('Get access_token').first().json.payload.data),
  ad_account_id: decode($('Get ad_account_id').first().json.payload.data),
  api_version: 'v22.0'
}}];

const ctx = $('Decode secrets').first().json;
const CLIENT_ID = ctx.client_id;
const AD_ACCOUNT = ctx.ad_account_id;
const INGESTED_AT = new Date().toISOString();
const num = v => (v === null || v === undefined || v === '' ? null : Number(v));
// INT64 columns must not receive 18234.0 — BigQuery rejects a decimal point in
// an INT64 load and reports it after the insert appears to have succeeded.
const int = v => (v === null || v === undefined || v === '' ? null : Math.round(Number(v)));
const pick = (arr, type) => {
  if (!Array.isArray(arr)) return null;
  const row = arr.find(a => a.action_type === type);
  return row ? Number(row.value) : null;
};
const rows = [];
for (const it of $input.all()) {
  const j = it.json;
  if (Array.isArray(j.data)) { for (const r of j.data) rows.push(r); }
  else if (j.ad_id || j.adset_id) { rows.push(j); }
}

return rows.map(r => ({ json: {
  client_id: CLIENT_ID,
  ingested_at: INGESTED_AT,
  ingest_source: 'cron',
  ad_account_id: AD_ACCOUNT,
  campaign_id: String(r.campaign_id ?? ''),
  campaign_name: r.campaign_name ?? '',
  adset_id: String(r.adset_id ?? ''),
  adset_name: r.adset_name ?? '',
  date_start: r.date_start,
  date_stop: r.date_stop,
  spend: num(r.spend),
  impressions: int(r.impressions),
  reach: int(r.reach),
  frequency: num(r.frequency),
  clicks: int(r.clicks),
  ctr: num(r.ctr),
  cpc: num(r.cpc),
  purchases:          int(pick(r.actions, 'omni_purchase') ?? pick(r.actions, 'purchase')),
  purchase_value:     num(pick(r.action_values, 'omni_purchase') ?? pick(r.action_values, 'purchase')),
  add_to_cart:        int(pick(r.actions, 'add_to_cart')),
  initiate_checkout:  int(pick(r.actions, 'initiate_checkout')),
  landing_page_views: int(pick(r.actions, 'landing_page_view')),
  link_clicks:        int(pick(r.actions, 'link_click')),
  outbound_clicks:    int(pick(r.outbound_clicks, 'outbound_click')),
  actions:       JSON.stringify(r.actions ?? []),
  action_values: JSON.stringify(r.action_values ?? []),
  payload_json:  JSON.stringify(r)
}}));

