}

// A breakdown row with no impressions is a bucket Meta had nothing to say
// about. Keeping it would inflate every "which age group" denominator with
// zeroes.
return rows.filter(r => Number(r.impressions) > 0).map(r => ({ json: {
  client_id: CLIENT_ID,
  ingested_at: INGESTED_AT,
  ad_account_id: AD_ACCOUNT,
  ad_id: String(r.ad_id),
  date_start: r.date_start,
  date_stop: r.date_stop,
  age: r.age ?? 'unknown',
  gender: r.gender ?? 'unknown',
  spend: num(r.spend),
  impressions: int(r.impressions),
  reach: int(r.reach),
  clicks: int(r.clicks),
  purchases:      int(pick(r.actions, 'omni_purchase') ?? pick(r.actions, 'purchase')),
  purchase_value: num(pick(r.action_values, 'omni_purchase') ?? pick(r.action_values, 'purchase')),
  payload_json: JSON.stringify(r)
}}));

